<script setup lang="tsx">
import type { WatchStopHandle } from "vue";
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, GetEllipsisText, ShowErrorTips } from "@/util/tips";
import { GetContestList, ParseContest } from "@/apis/contest.ts";
import { handleGotoUsername } from "@/util/router.ts";
import { Contest, ContestView } from "@/types/contest.ts";
import type { TableRowData, TNodeReturnValue } from "tdesign-vue-next";
import type { CellParams } from "@/types/table";
import { useBreakpoint } from "@/composables/useBreakpoint";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

let viewActive = false;
let watchHandle: WatchStopHandle | null = null;

// 说明：tdesign 的 BaseTableCol<T> 是递归类型（children?: BaseTableCol<T>[]），本页列较多且 cell 返回 JSX，
// 直接标注会触发 TS2589（Type instantiation is excessively deep），故按其字段构造一个非递归的等价列类型
type ContestListColumn = {
  title: string;
  colKey: string;
  width?: number;
  cell?: (_h: unknown, data: CellParams<TableRowData>) => TNodeReturnValue;
};

const listColumns = ref<ContestListColumn[]>([
  {
    title: "ID",
    colKey: "id",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-button variant="text" onClick={() => handleGotoContest(data.row.id)}>
          {data.row.id}
        </t-button>
      );
    },
  },
  {
    title: "标题",
    colKey: "title",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const text = GetEllipsisText(data.row.title, 25);
      return (
        <t-space size="small" breakLine={false}>
          {data.row.isReplay ? (
            <t-tag theme="warning" variant="light" size="small">
              回放
            </t-tag>
          ) : null}
          <t-tooltip content={data.row.title}>
            <t-button variant="text" onClick={() => handleGotoContest(data.row.id)}>
              {text}
            </t-button>
          </t-tooltip>
        </t-space>
      );
    },
  },
  {
    title: "负责人",
    colKey: "inserterNickname",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-button variant="text" onClick={() => handleGotoUsername(router, data.row.inserterUsername)}>
          {data.row.inserterNickname}
        </t-button>
      );
    },
  },
  {
    title: "开始时间",
    colKey: "startTime",
  },
  {
    title: "时长",
    colKey: "endTime",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const startTime = data.row.startTime as string;
      const endTime = data.row.endTime as string;
      const duration = Date.parse(endTime) - Date.parse(startTime);
      return `${Math.round((duration / (1000 * 60) / 60) * 10) / 10} 小时`;
    },
  },
  {
    title: "状态",
    colKey: "status",
    width: 90,
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const nowTime = data.row.nowTime;
      const startTime = new Date(data.row.startTime);
      const endTime = new Date(data.row.endTime);
      if (nowTime >= startTime && nowTime <= endTime) {
        const totalDuration = endTime.getTime() - startTime.getTime();
        const elapsedDuration = nowTime.getTime() - startTime.getTime();
        let percentage = Math.round((elapsedDuration / totalDuration) * 1000) / 10;
        if (percentage >= 100) {
          percentage = 99.99;
        }
        return (
          <t-progress
            color="#00B16B"
            status="active"
            theme="plump"
            percentage={percentage}
            label={() => {
              return percentage.toString() + "%";
            }}
          />
        );
      } else if (nowTime > endTime) {
        return (
          <t-tag theme="danger" variant="light">
            已结束
          </t-tag>
        );
      } else {
        return (
          <t-tag theme="warning" variant="light">
            未开始
          </t-tag>
        );
      }
    },
  },
  {
    title: "权限",
    colKey: "private",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      if (data.row.private) {
        return (
          <t-tag theme="danger" variant="outline">
            私有
          </t-tag>
        );
      } else {
        return (
          <t-tag theme="success" variant="outline">
            公开
          </t-tag>
        );
      }
    },
  },
]);

const dataLoading = ref(false);

let currentPage = 1;
let currentPageSize = 50;

// 定时器句柄（清理时置为 null）
let updateTimerHandle: number | null = -1;

const pagination = ref({
  current: currentPage,
  pageSize: currentPageSize,
  defaultCurrent: currentPage,
  defaultPageSize: currentPageSize,
  total: 0,
  pageSizeOptions: [50, 100],
});

const contestViews = ref<ContestView[]>();

// 显式标注返回类型：列类型为上面的非递归等价类型，避免推断时再次实例化递归泛型
const visibleColumns = computed<ContestListColumn[]>(() => {
  if (isMobile.value) {
    return listColumns.value.filter(
      (col) => col.colKey !== "inserterNickname" && col.colKey !== "private"
    );
  }
  return listColumns.value;
});

const contestSearchForm = ref({
  title: "",
  username: "",
});

const handleGotoContest = (id: string) => {
  if (!id) {
    return;
  }
  router.push({ path: "/contest/" + id });
};

const handleSearchContest = async () => {
  await router.push({
    query: {
      ...route.query,
      title: contestSearchForm.value.title,
      username: contestSearchForm.value.username,
      page: 1,
      page_size: pagination.value.defaultPageSize,
    },
  });
};

const handleResetSearch = async () => {
  contestSearchForm.value.title = "";
  contestSearchForm.value.username = "";
  await router.push({
    query: {
      ...route.query,
      title: "",
      username: "",
      page: 1,
      page_size: pagination.value.defaultPageSize,
    },
  });
};

// 移动端筛选 Drawer 显隐状态
const showFilterDrawer = ref(false);

// 当前已激活的筛选条件数量，用于「筛选」按钮徽标提示
const activeFilterCount = computed(() => {
  let count = 0;
  if (contestSearchForm.value.title) count++;
  if (contestSearchForm.value.username) count++;
  return count;
});

// 移动端 Drawer 中的搜索：复用桌面端逻辑，搜索后关闭抽屉
const handleDrawerSearch = async () => {
  await handleSearchContest();
  showFilterDrawer.value = false;
};

// 移动端 Drawer 中的重置：复用桌面端逻辑
const handleDrawerReset = async () => {
  await handleResetSearch();
};

const handleUpdateNowTime = () => {
  const now = new Date();
  if (contestViews.value) {
    for (let i = 0; i < contestViews.value.length; i++) {
      contestViews.value[i].nowTime = now;
    }
  }
};

const fetchData = async (paginationInfo: { current: number; pageSize: number }, needLoading: boolean) => {
  if (needLoading) {
    dataLoading.value = true;
  }
  try {
    const { current, pageSize } = paginationInfo;
    const res = await GetContestList(contestSearchForm.value.title, contestSearchForm.value.username, current, pageSize);
    contestViews.value = [];
    if (res.code === 0) {
      const responseList = res.data.list as Contest[];
      if (responseList) {
        for (let i = 0; i < responseList.length; i++) {
          const item = responseList[i];
          const result = ParseContest(item);
          contestViews.value?.push(result);
        }
      }
      pagination.value = { ...pagination.value, total: res.data.total_count };

      handleUpdateNowTime();
      updateTimerHandle = window.setInterval(() => {
        if (!viewActive) {
          if (updateTimerHandle) {
            clearInterval(updateTimerHandle);
            updateTimerHandle = null;
          }
          return;
        }
        handleUpdateNowTime();
      }, 1000); // 每分钟更新一次当前时间显示
    } else {
      if (needLoading) {
        ShowErrorTips(globalProperties, res.code);
      }
    }
  } catch (err) {
    console.error(err);
    if (needLoading) {
      ShowErrorTips(globalProperties, GetCommonErrorCode());
    }
  } finally {
    if (needLoading) {
      dataLoading.value = false;
    }
  }
};

const onPageChange = async (pageInfo: { current: number; pageSize: number }) => {
  // 更新 URL 查询参数
  await router.push({
    query: { ...route.query, page: pageInfo.current, page_size: pageInfo.pageSize },
  });
};

const handleCreateContest = () => {
  router.push({ name: "contest-create" });
};

// 新建回放比赛：「上传榜单生成回放」的入口从比赛编辑页搬到这里（回放比赛是一等公民比赛）
const handleCreateReplayContest = () => {
  router.push({ name: "contest-replay-create" });
};

// 初始化分页信息
onMounted(async () => {
  viewActive = true;

  watchHandle = watch(
    () => route.query,
    (newQuery) => {
      contestSearchForm.value.title = (newQuery.title as string) || "";
      contestSearchForm.value.username = (newQuery.username as string) || "";
      const queryPage = parseInt(newQuery.page as string) || pagination.value.defaultCurrent;
      const queryPageSize = parseInt(newQuery.page_size as string) || pagination.value.defaultPageSize;
      currentPage = queryPage;
      currentPageSize = queryPageSize;
      pagination.value = { ...pagination.value, current: currentPage, pageSize: currentPageSize };
      fetchData({ current: currentPage, pageSize: currentPageSize }, true);
    },
    { immediate: true }
  );
});

onBeforeUnmount(() => {
  viewActive = false;

  if (watchHandle) {
    watchHandle();
  }
});
</script>

<template>
  <!-- 移动端布局：顶部操作栏 + 列表 + 右侧筛选 Drawer -->
  <div v-if="isMobile" class="contest-list-mobile">
    <div class="mobile-toolbar">
      <t-button
        theme="default"
        variant="outline"
        class="mobile-toolbar-btn"
        @click="showFilterDrawer = true"
      >
        <template #icon>
          <t-icon name="filter" />
        </template>
        筛选
        <t-badge
          v-if="activeFilterCount > 0"
          :count="activeFilterCount"
          shape="round"
          color="var(--td-brand-color)"
          :offset="[6, -6]"
        />
      </t-button>
      <t-button theme="default" variant="outline" class="mobile-toolbar-btn" @click="handleCreateReplayContest">
        <template #icon>
          <t-icon name="time" />
        </template>
        回放
      </t-button>
      <t-button theme="primary" class="mobile-toolbar-btn" @click="handleCreateContest">
        <template #icon>
          <t-icon name="add" />
        </template>
        创建
      </t-button>
    </div>

    <t-card class="mobile-list-card">
      <div style="overflow-x: auto; width: 100%">
        <t-table
          :data="contestViews"
          :columns="visibleColumns"
          row-key="id"
          vertical-align="top"
          :hover="true"
          :pagination="pagination"
          :loading="dataLoading"
          table-layout="auto"
          size="small"
          style="white-space: nowrap"
          @page-change="onPageChange"
        />
      </div>
    </t-card>

    <!-- 移动端筛选抽屉：复用桌面端筛选表单 -->
    <t-drawer
      v-model:visible="showFilterDrawer"
      header="筛选"
      placement="right"
      size="80%"
      :close-on-esc-keydown="true"
      :show-overlay="true"
    >
      <t-form :model="contestSearchForm" @submit="handleDrawerSearch" @reset="handleDrawerReset">
        <t-form-item label="标题">
          <t-input v-model="contestSearchForm.title" placeholder="暂不支持模糊查询"></t-input>
        </t-form-item>
        <t-form-item label="负责人">
          <t-input v-model="contestSearchForm.username" placeholder="仅支持输入完整用户名"></t-input>
        </t-form-item>
      </t-form>

      <template #footer>
        <t-space>
          <t-button theme="primary" @click="handleDrawerSearch">确定</t-button>
          <t-button theme="danger" variant="outline" @click="handleDrawerReset">重置</t-button>
        </t-space>
      </template>
    </t-drawer>
  </div>

  <!-- 桌面端布局：左右双栏，筛选在右侧 -->
  <t-row v-else>
    <t-col :span="9">
      <t-card style="margin: 10px">
        <div style="overflow-x: auto; width: 100%">
          <t-table
            :data="contestViews"
            :columns="visibleColumns"
            row-key="id"
            vertical-align="top"
            :hover="true"
            :pagination="pagination"
            :loading="dataLoading"
            table-layout="auto"
            size="medium"
            style="white-space: nowrap"
            @page-change="onPageChange"
          />
        </div>
      </t-card>
    </t-col>
    <t-col :span="3">
      <div style="margin: 10px">
        <t-card class="sh-card">
          <t-form :model="contestSearchForm" @submit="handleSearchContest" @reset="handleResetSearch">
            <t-form-item label="标题">
              <t-input v-model="contestSearchForm.title" placeholder="暂不支持模糊查询"></t-input>
            </t-form-item>
            <t-form-item label="负责人">
              <t-input v-model="contestSearchForm.username" placeholder="仅支持输入完整用户名"></t-input>
            </t-form-item>
            <t-form-item>
              <t-space>
                <t-button theme="primary" type="submit">提交</t-button>
                <t-button theme="danger" type="reset">重置</t-button>
              </t-space>
            </t-form-item>
          </t-form>
        </t-card>
        <t-card class="sh-card">
          <t-space>
            <t-button @click="handleCreateContest">创建</t-button>
            <t-button @click="handleCreateReplayContest">新建回放比赛</t-button>
          </t-space>
        </t-card>
      </div>
    </t-col>
  </t-row>
</template>

<style scoped>
.sh-card {
  margin: 10px;
}

/* 移动端列表页样式 */
.contest-list-mobile {
  padding: 10px;
}

.mobile-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

/* 工具栏按钮平分剩余空间，让「筛选」和「创建」并排显示 */
.mobile-toolbar-btn {
  flex: 1;
}

.mobile-list-card {
  margin: 0;
}
</style>
